import { describe, expect, it, vi } from "vitest";
import {
  ConfirmationDecoratorCommand,
  declareCapabilities,
  MessageHub,
  RxDispatcher,
} from "@thekaveh/vmx";
import {
  Notification,
  NotificationHub,
} from "@thekaveh/vmx/notifications";

import { InMemoryNoteRepository } from "../../src/models/inMemoryRepository.js";
import type { NoteModel } from "../../src/models/noteModel.js";
import type { NotebookModel } from "../../src/models/notebookModel.js";
import { buildSeed } from "../../src/models/seed.js";
import { CapabilityActionsVM } from "../../src/viewmodels/capabilityActionsVM.js";
import { NotebooksRootVM } from "../../src/viewmodels/notebooksRootVM.js";
import { NotebookVM } from "../../src/viewmodels/notebookVM.js";
import { NoteVM } from "../../src/viewmodels/noteVM.js";

function makeNotebook(): NotebookVM {
  const hub = new MessageHub();
  const vm = NotebookVM.builder()
    .name("nb:test")
    .model({ id: "nb-test", name: "T", parentId: null } satisfies NotebookModel)
    .services(hub, RxDispatcher.immediate())
    .build();
  vm.construct();
  return vm;
}

function makeNote(): NoteVM {
  const hub = new MessageHub();
  const model: NoteModel = {
    id: "note-test",
    notebookId: "nb-test",
    title: "T",
    tags: [],
    body: "",
    starred: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  const vm = NoteVM.builder()
    .name("note:test")
    .model(model)
    .services(hub, RxDispatcher.immediate())
    .build();
  vm.construct();
  return vm;
}

function makeCap(getter: () => object | null): CapabilityActionsVM {
  const hub = new MessageHub();
  const vm = CapabilityActionsVM.builder()
    .name("capabilities")
    .services(hub, RxDispatcher.immediate())
    .focusedGetter(getter)
    .build();
  vm.construct();
  return vm;
}

describe("CapabilityActionsVM", () => {
  it("empty list when nothing is focused", () => {
    const vm = makeCap(() => null);
    expect(vm.actions.value).toEqual([]);
  });

  it("projects a notebook's capability surface", () => {
    const nb = makeNotebook();
    const vm = makeCap(() => nb);
    const labels = vm.actions.value.map((a) => a.label);
    expect(labels).toContain("Select");
    expect(labels).toContain("Expand");
    expect(labels).toContain("Collapse");
    expect(labels).toContain("Toggle Expansion");
    expect(labels).toContain("Reconstruct");
    // Notebook is NOT a NoteVM so Save/Delete must be absent.
    expect(labels).not.toContain("Save");
    expect(labels).not.toContain("Delete");
  });

  it("includes Save and Delete only for a NoteVM target", () => {
    const note = makeNote();
    const vm = makeCap(() => note);
    const labels = vm.actions.value.map((a) => a.label);
    expect(labels).toContain("Save");
    expect(labels).toContain("Delete");
    expect(labels).toContain("Close");
  });

  it("recomputeActions republishes the derived list", () => {
    let focused: object | null = null;
    const vm = makeCap(() => focused);
    expect(vm.actions.value.length).toBe(0);
    const nb = makeNotebook();
    focused = nb;
    vm.recomputeActions();
    expect(vm.actions.value.length).toBeGreaterThan(0);
  });

  it("each action command is executable end-to-end", () => {
    const nb = makeNotebook();
    const vm = makeCap(() => nb);
    const toggle = vm.actions.value.find((a) => a.label === "Toggle Expansion");
    expect(toggle).toBeDefined();
    expect(nb.isExpanded).toBe(false);
    toggle!.command.execute();
    expect(nb.isExpanded).toBe(true);
  });

  it("dispose tears down without throwing", () => {
    const vm = makeCap(() => null);
    expect(() => vm.dispose()).not.toThrow();
  });

  it("builder validates required fields", () => {
    expect(() => CapabilityActionsVM.builder().build()).toThrow();
  });

  it("focusedVM getter delegates to the supplied getter", () => {
    const nb = makeNotebook();
    const vm = makeCap(() => nb);
    expect(vm.focusedVM).toBe(nb);
  });

  it("projects every other capability label when the marker is set", () => {
    // A bag-of-markers stub: declares every capability the projector knows
    // about and supplies stub methods so each command can be built / fired.
    const allCaps = {
      canSelect: vi.fn(() => true),
      select: vi.fn(),
      canDeselect: vi.fn(() => true),
      deselect: vi.fn(),
      canToggleSelection: vi.fn(() => true),
      toggleSelection: vi.fn(),
      canExpand: vi.fn(() => true),
      expand: vi.fn(),
      canCollapse: vi.fn(() => true),
      collapse: vi.fn(),
      canToggleExpansion: vi.fn(() => true),
      toggleExpansion: vi.fn(),
      canClose: vi.fn(() => true),
      close: vi.fn(),
      canApprove: vi.fn(() => true),
      approve: vi.fn(),
      canCancel: vi.fn(() => true),
      cancel: vi.fn(),
      canCreateNew: vi.fn(() => true),
      createNew: vi.fn(),
      canReconstruct: vi.fn(() => true),
      reconstruct: vi.fn(),
    };
    declareCapabilities(
      allCaps,
      "ISelectable",
      "IDeselectable",
      "ISelectionTogglable",
      "IExpandable",
      "ICollapsible",
      "IExpansionTogglable",
      "IClosable",
      "IApprovable",
      "ICancelable",
      "INewCreatable",
      "IReconstructable",
    );
    const out = CapabilityActionsVM.project(allCaps);
    const labels = out.map((a) => a.label);
    expect(labels).toEqual([
      "Select",
      "Deselect",
      "Toggle Selection",
      "Expand",
      "Collapse",
      "Toggle Expansion",
      "Close",
      "Approve",
      "Cancel",
      "New",
      "Reconstruct",
    ]);
    // Execute each command to ensure the wiring is sound and stubs were hit.
    for (const a of out) a.command.execute();
    expect(allCaps.select).toHaveBeenCalled();
    expect(allCaps.deselect).toHaveBeenCalled();
    expect(allCaps.toggleSelection).toHaveBeenCalled();
    expect(allCaps.expand).toHaveBeenCalled();
    expect(allCaps.collapse).toHaveBeenCalled();
    expect(allCaps.toggleExpansion).toHaveBeenCalled();
    expect(allCaps.close).toHaveBeenCalled();
    expect(allCaps.approve).toHaveBeenCalled();
    expect(allCaps.cancel).toHaveBeenCalled();
    expect(allCaps.createNew).toHaveBeenCalled();
    expect(allCaps.reconstruct).toHaveBeenCalled();
  });

  it("notebooks root (INewCreatable) projects a 'New' action", () => {
    const hub = new MessageHub();
    const repo = new InMemoryNoteRepository(buildSeed(), {
      loadAllDelayMs: 0,
      addNotebookDelayMs: 0,
    });
    const root = NotebooksRootVM.builder()
      .name("root")
      .services(hub, RxDispatcher.immediate())
      .repository(repo)
      .build();
    root.construct();
    const out = CapabilityActionsVM.project(root);
    expect(out.map((a) => a.label)).toContain("New");
  });

  // ── shared delete-command behavior: capability-bar Delete reuses NoteVM.deleteCommand ─
  // so the ConfirmationDecoratorCommand + "Note deleted" notification fire
  // from the action-bar identically to the in-list delete button. Prior
  // code built a fresh RelayCommand that called note.delete() directly,
  // bypassing the gate. Parity with C# (CapabilityActionsVM.cs:121-131)
  // and Python.

  function makeNoteWithConfirm(
    confirmResult: boolean,
    notificationHub: NotificationHub | null = null,
  ): { note: NoteVM; deleted: boolean[] } {
    const deleted: boolean[] = [];
    const hub = new MessageHub();
    const model: NoteModel = {
      id: "note-cap",
      notebookId: "nb-cap",
      title: "T",
      tags: [],
      body: "",
      starred: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    let builder = NoteVM.builder()
      .name("note:cap")
      .model(model)
      .services(hub, RxDispatcher.immediate())
      .onDelete(() => {
        deleted.push(true);
      })
      .confirmDelete(async () => confirmResult);
    if (notificationHub !== null) {
      builder = builder.notificationHub(notificationHub);
    }
    const note = builder.build();
    note.construct();
    return { note, deleted };
  }

  it("capability-bar Delete reuses note.deleteCommand (confirm=false → no delete)", async () => {
    const { note, deleted } = makeNoteWithConfirm(false);
    expect(note.deleteCommand).toBeInstanceOf(ConfirmationDecoratorCommand);
    const cap = makeCap(() => note);
    const action = cap.actions.value.find((a) => a.label === "Delete");
    expect(action).toBeDefined();
    // Same wrapped reference as note.deleteCommand (parity contract).
    expect(action!.command).toBe(note.deleteCommand);
    await (action!.command as ConfirmationDecoratorCommand).executeAsync();
    expect(deleted).toEqual([]);
  });

  it("capability-bar Delete fires notification when confirm=true", async () => {
    const notifs = new NotificationHub();
    const observed: Notification[] = [];
    notifs.pending.subscribe((snap) => {
      for (const n of snap) {
        if (!observed.includes(n)) observed.push(n);
      }
    });
    const { note, deleted } = makeNoteWithConfirm(true, notifs);
    const cap = makeCap(() => note);
    const action = cap.actions.value.find((a) => a.label === "Delete");
    await (action!.command as ConfirmationDecoratorCommand).executeAsync();
    expect(deleted).toEqual([true]);
    expect(observed.some((n) => n.message.includes("Note deleted"))).toBe(true);
  });
});

using System.Reactive.Concurrency;
using NotesShowcase.Models;
using NotesShowcase.ViewModels;
using VMx.Commands;
using VMx.Notifications;
using VMx.Services;
using Xunit;

namespace NotesShowcase.Tests.ViewModels;

public sealed class CapabilityActionsVMTests
{
    private static CapabilityActionsVM Build(Func<object?> getter)
    {
        var hub = new MessageHub();
        var dispatcher = new RxDispatcher(ImmediateScheduler.Instance, ImmediateScheduler.Instance);
        var vm = CapabilityActionsVM.Builder()
            .Name("caps").Services(hub, dispatcher).FocusedGetter(getter).Build();
        vm.Construct();
        return vm;
    }

    private static NotebookVM SampleNotebook()
    {
        var hub = new MessageHub();
        var dispatcher = new RxDispatcher(ImmediateScheduler.Instance, ImmediateScheduler.Instance);
        var vm = NotebookVM.Builder()
            .Name("nb").Services(hub, dispatcher)
            .Model(new NotebookModel("nb-1", "Work", null))
            .Build();
        vm.Construct();
        return vm;
    }

    private static NoteVM SampleNote()
    {
        var hub = new MessageHub();
        var dispatcher = new RxDispatcher(ImmediateScheduler.Instance, ImmediateScheduler.Instance);
        var model = new NoteModel("n-1", "nb-1", "T", Array.Empty<string>(), "", false,
            DateTimeOffset.UtcNow, DateTimeOffset.UtcNow);
        var vm = NoteVM.Builder()
            .Name("note").Services(hub, dispatcher).Model(model).Build();
        vm.Construct();
        return vm;
    }

    [Fact]
    public void Notebook_in_focus_yields_Expand_Collapse_Toggle_Select_actions()
    {
        var nb = SampleNotebook();
        var vm = Build(() => nb);
        var labels = vm.Actions.Value.Select(a => a.Label).ToList();
        Assert.Contains("Expand", labels);
        Assert.Contains("Collapse", labels);
        Assert.Contains("Toggle Expansion", labels);
        Assert.Contains("Select", labels);
        // No note-specific actions.
        Assert.DoesNotContain("Close", labels);
        Assert.DoesNotContain("Delete", labels);
    }

    [Fact]
    public void Note_in_focus_yields_Close_Save_Delete_Select_actions()
    {
        var note = SampleNote();
        var vm = Build(() => note);
        var labels = vm.Actions.Value.Select(a => a.Label).ToList();
        Assert.Contains("Close", labels);
        Assert.Contains("Save", labels);
        Assert.Contains("Delete", labels);
        Assert.Contains("Select", labels);
        // No notebook expansion actions.
        Assert.DoesNotContain("Expand", labels);
    }

    [Fact]
    public void Null_focus_yields_empty_actions()
    {
        var vm = Build(() => null);
        Assert.Empty(vm.Actions.Value);
    }

    [Fact]
    public async Task AddNoteCommand_delegates_to_host_predicate_and_action()
    {
        var canAdd = false;
        var calls = 0;
        var hub = new MessageHub();
        var dispatcher = new RxDispatcher(ImmediateScheduler.Instance, ImmediateScheduler.Instance);
        var vm = CapabilityActionsVM.Builder()
            .Name("caps")
            .Services(hub, dispatcher)
            .FocusedGetter(() => null)
            .CanAddNote(() => canAdd)
            .AddNoteAction(() => calls++)
            .Build();
        vm.Construct();

        Assert.False(vm.AddNoteCommand.CanExecute(null));
        await Assert.IsType<AsyncRelayCommand>(vm.AddNoteCommand).ExecuteAsync();
        Assert.Equal(0, calls);

        canAdd = true;

        Assert.True(vm.AddNoteCommand.CanExecute(null));
        await Assert.IsType<AsyncRelayCommand>(vm.AddNoteCommand).ExecuteAsync();
        Assert.Equal(1, calls);
    }

    [Fact]
    public void RecomputeActions_picks_up_focus_change()
    {
        object? focused = SampleNotebook();
        var vm = Build(() => focused);
        Assert.Contains("Expand", vm.Actions.Value.Select(a => a.Label));
        focused = SampleNote();
        vm.RecomputeActions();
        Assert.Contains("Close", vm.Actions.Value.Select(a => a.Label));
        Assert.DoesNotContain("Expand", vm.Actions.Value.Select(a => a.Label));
    }

    [Fact]
    public void Each_action_CanExecute_follows_underlying_predicate()
    {
        var nb = SampleNotebook(); // initially collapsed
        var vm = Build(() => nb);
        var expand = vm.Actions.Value.First(a => a.Label == "Expand");
        var collapse = vm.Actions.Value.First(a => a.Label == "Collapse");
        Assert.True(expand.Command.CanExecute(null));
        Assert.False(collapse.Command.CanExecute(null));
        nb.Expand();
        // Stale actions reflect the old predicate snapshot — by spec §14.4 the
        // host re-projects on focus changes; here we re-project to confirm
        // the new state is captured.
        vm.RecomputeActions();
        var collapse2 = vm.Actions.Value.First(a => a.Label == "Collapse");
        Assert.True(collapse2.Command.CanExecute(null));
    }

    // ── shared delete-command behavior: capability-bar Delete reuses
    // NoteVM.DeleteCommand (the wrapped ConfirmationDecoratorCommand) so the
    // action-bar Delete cancels on "No" and fires the "Note deleted"
    // notification on "Yes" — identical behaviour to the in-list delete
    // button. Mirrors Py / TS tests of the same name.

    private static NoteVM NoteWithConfirm(bool confirmResult, INotificationHub? nh = null, Action<NoteVM>? onDelete = null)
    {
        var hub = new MessageHub();
        var dispatcher = new RxDispatcher(ImmediateScheduler.Instance, ImmediateScheduler.Instance);
        var model = new NoteModel("n-cap", "nb-cap", "T", Array.Empty<string>(), "", false,
            DateTimeOffset.UtcNow, DateTimeOffset.UtcNow);
        var builder = NoteVM.Builder()
            .Name("note:cap").Services(hub, dispatcher).Model(model)
            .OnDelete(onDelete ?? (_ => { }))
            .ConfirmDelete(_ => Task.FromResult(confirmResult));
        if (nh is not null) builder = builder.NotificationHub(nh);
        var vm = builder.Build();
        vm.Construct();
        return vm;
    }

    [Fact]
    public async Task Capability_bar_Delete_reuses_note_DeleteCommand_confirm_false_does_NOT_delete()
    {
        var deleted = new List<bool>();
        var note = NoteWithConfirm(confirmResult: false, onDelete: _ => deleted.Add(true));
        Assert.IsType<ConfirmationDecoratorCommand>(note.DeleteCommand);
        var caps = Build(() => note);
        var delete = caps.Actions.Value.First(a => a.Label == "Delete");
        // Same wrapped reference (parity contract with Py / TS).
        Assert.Same(note.DeleteCommand, delete.Command);
        await ((ConfirmationDecoratorCommand)delete.Command).ExecuteAsync(null);
        Assert.Empty(deleted);
    }

    [Fact]
    public async Task Capability_bar_Delete_with_confirm_true_invokes_OnDelete_and_publishes_notification()
    {
        using var notificationHub = new NotificationHub();
        var observed = new List<Notification>();
        using var sub = notificationHub.Pending.Subscribe(snap =>
        {
            foreach (var n in snap) if (!observed.Contains(n)) observed.Add(n);
        });
        var deleted = new List<bool>();
        var note = NoteWithConfirm(confirmResult: true, nh: notificationHub,
            onDelete: _ => deleted.Add(true));
        var caps = Build(() => note);
        var delete = caps.Actions.Value.First(a => a.Label == "Delete");
        await ((ConfirmationDecoratorCommand)delete.Command).ExecuteAsync(null);
        Assert.Single(deleted);
        Assert.Contains(observed, n => n.Message.Contains("Note deleted"));
    }
}

{
  "name": "vmx-integration-recipes",
  "private": true,
  "version": "0.0.0",
  "description": "Executes the Vue, Solid and Svelte integration recipes from docs/content/integration against pinned host versions.",
  "type": "module",
  "scripts": {
    "test": "vitest run",
    "typecheck": "tsc --noEmit",
    "check:deps": "npm ls --all --omit=optional"
  },
  "dependencies": {
    "@thekaveh/vmx": "file:../../../langs/typescript",
    "rxjs": "^7.8.1",
    "solid-js": "1.9.16",
    "svelte": "5.57.1",
    "vue": "3.5.43"
  },
  "devDependencies": {
    "@sveltejs/vite-plugin-svelte": "^7.3.1",
    "@vitejs/plugin-vue": "^6.0.0",
    "jsdom": "^29.1.1",
    "typescript": "^6.0.3",
    "vite": "^8.3.2",
    "vite-plugin-solid": "^2.11.0",
    "vitest": "^5.0.0"
  },
  "engines": {
    "node": "^20.19.0 || ^22.13.0 || >=24.0.0"
  }
}

/**
 * ActionVM — pure presentation record for one capability-derived action.
 *
 * Used by CapabilityActionsVM to project a focused VM's capability surface
 * into a flat list of (label, command) tuples for the view layer (Phase 5.c).
 *
 * See spec §14.4 (capability dispatch) and the C# `ActionVM.cs` parity record.
 */
import type { ICommand } from "@thekaveh/vmx";

export interface ActionVM {
  readonly label: string;
  readonly command: ICommand;
}

/** Helper factory mirroring the C# / Python `ActionVM(label, command)` constructor. */
export function makeActionVM(label: string, command: ICommand): ActionVM {
  return { label, command };
}

/**
 * CapabilityActionsVM — projects a focused VM's capability surface into a
 * flat list of `ActionVM`s for the capability-action bar (spec §14.4).
 *
 * VMx-API adaptation: TypeScript's interfaces are structural, but the
 * capability registry (CAP-020) requires explicit `declareCapabilities`
 * markers — we use `hasCapability` instead of `instanceof` checks for
 * capability discovery. NoteVM (the only example-defined target of
 * `IDeletable<NoteVM>` / `ISavable<NoteVM>`) is detected by `instanceof`
 * so we can wire the right argument.
 */
import { BehaviorSubject, map } from "rxjs";
import {
  AsyncRelayCommand,
  ComponentVMBase,
  DerivedProperty,
  hasCapability,
  RelayCommand,
  ViewModelType,
  type ICommand,
  type IDispatcher,
  type IMessageHub,
} from "@thekaveh/vmx";

import { type ActionVM, makeActionVM } from "./actionVM.js";
import { NoteVM } from "./noteVM.js";

type FocusedGetter = () => object | null;

interface SelectionShape {
  canSelect(): boolean;
  select(): void;
}
interface DeselectionShape {
  canDeselect(): boolean;
  deselect(): void;
}
interface ToggleSelectionShape {
  canToggleSelection(): boolean;
  toggleSelection(): void;
}
interface ExpandShape {
  canExpand(): boolean;
  expand(): void;
}
interface CollapseShape {
  canCollapse(): boolean;
  collapse(): void;
}
interface ToggleExpansionShape {
  canToggleExpansion(): boolean;
  toggleExpansion(): void;
}
interface ClosableShape {
  canClose(): boolean;
  close(): void;
}
interface ApprovableShape {
  canApprove(): boolean;
  approve(): void;
}
interface CancelableShape {
  canCancel(): boolean;
  cancel(): void;
}
interface NewCreatableShape {
  canCreateNew(): boolean;
  createNew(): void;
}
interface ReconstructShape {
  canReconstruct(): boolean;
  reconstruct(): void;
}

export class CapabilityActionsVM extends ComponentVMBase {
  readonly #focusedGetter: FocusedGetter;
  readonly #focusSubject: BehaviorSubject<object | null>;
  readonly #actionsDerived: DerivedProperty<readonly ActionVM[]>;
  // Edge-case backfill (readonly notebook gating): a dedicated *Add Note*
  // command whose `canExecute` predicate consults the host-supplied
  // `canAddNote` callback. The host (e.g. `WorkspaceVM`) wires this to
  // `!notesView.currentNotebookIsReadonly`. Defaults stay backward-compatible:
  // a no-op action and an always-true predicate.
  readonly #addNoteCommand: AsyncRelayCommand;

  constructor(opts: {
    name: string;
    hint: string;
    hub: IMessageHub;
    dispatcher: IDispatcher;
    focusedGetter: FocusedGetter;
    addNoteAction?: () => void | Promise<void>;
    canAddNote?: () => boolean;
  }) {
    super({
      name: opts.name,
      hint: opts.hint,
      hub: opts.hub,
      dispatcher: opts.dispatcher,
    });
    this.#focusedGetter = opts.focusedGetter;
    this.#focusSubject = new BehaviorSubject<object | null>(
      opts.focusedGetter(),
    );
    this.#actionsDerived = new DerivedProperty<readonly ActionVM[]>(
      this.#focusSubject.pipe(map((f) => CapabilityActionsVM.project(f))),
      null,
      null,
    );
    const addNoteAction = opts.addNoteAction ?? ((): void => undefined);
    const canAddNote = opts.canAddNote ?? ((): boolean => true);
    this.#addNoteCommand = AsyncRelayCommand.builder()
      .predicate(canAddNote)
      .task(async () => { await addNoteAction(); })
      .build();
  }

  get type(): ViewModelType {
    return ViewModelType.Component;
  }

  get hub(): IMessageHub {
    return this._hub;
  }

  get focusedVM(): object | null {
    return this.#focusedGetter();
  }

  /** Live projection: list of (label, command) for the focused VM. */
  get actions(): DerivedProperty<readonly ActionVM[]> {
    return this.#actionsDerived;
  }

  /**
   * Host-driven *Add Note* command.
   *
   * Edge-case backfill (readonly notebook gating): `canExecute` delegates
   * to the `canAddNote` callback supplied at construction. `WorkspaceVM`
   * wires the predicate to `!notesView.currentNotebookIsReadonly` so the
   * bar gates adding notes to readonly notebooks.
   */
  get addNoteCommand(): ICommand {
    return this.#addNoteCommand;
  }

  /**
   * Re-projects the action list from the current focused VM. The host calls
   * this after focus changes (typically via a hub subscription).
   */
  recomputeActions(): void {
    this.#focusSubject.next(this.#focusedGetter());
  }

  static project(focused: object | null): readonly ActionVM[] {
    if (focused === null) return [];
    const out: ActionVM[] = [];

    if (hasCapability(focused, "ISelectable")) {
      const f = focused as SelectionShape;
      out.push(
        makeActionVM(
          "Select",
          RelayCommand.builder()
            .predicate(() => f.canSelect())
            .task(() => f.select())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "IDeselectable")) {
      const f = focused as DeselectionShape;
      out.push(
        makeActionVM(
          "Deselect",
          RelayCommand.builder()
            .predicate(() => f.canDeselect())
            .task(() => f.deselect())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "ISelectionTogglable")) {
      const f = focused as ToggleSelectionShape;
      out.push(
        makeActionVM(
          "Toggle Selection",
          RelayCommand.builder()
            .predicate(() => f.canToggleSelection())
            .task(() => f.toggleSelection())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "IExpandable")) {
      const f = focused as ExpandShape;
      out.push(
        makeActionVM(
          "Expand",
          RelayCommand.builder()
            .predicate(() => f.canExpand())
            .task(() => f.expand())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "ICollapsible")) {
      const f = focused as CollapseShape;
      out.push(
        makeActionVM(
          "Collapse",
          RelayCommand.builder()
            .predicate(() => f.canCollapse())
            .task(() => f.collapse())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "IExpansionTogglable")) {
      const f = focused as ToggleExpansionShape;
      out.push(
        makeActionVM(
          "Toggle Expansion",
          RelayCommand.builder()
            .predicate(() => f.canToggleExpansion())
            .task(() => f.toggleExpansion())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "IClosable")) {
      const f = focused as ClosableShape;
      out.push(
        makeActionVM(
          "Close",
          RelayCommand.builder()
            .predicate(() => f.canClose())
            .task(() => f.close())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "IApprovable")) {
      const f = focused as ApprovableShape;
      out.push(
        makeActionVM(
          "Approve",
          RelayCommand.builder()
            .predicate(() => f.canApprove())
            .task(() => f.approve())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "ICancelable")) {
      const f = focused as CancelableShape;
      out.push(
        makeActionVM(
          "Cancel",
          RelayCommand.builder()
            .predicate(() => f.canCancel())
            .task(() => f.cancel())
            .build(),
        ),
      );
    }
    if (hasCapability(focused, "INewCreatable")) {
      const f = focused as NewCreatableShape;
      out.push(
        makeActionVM(
          "New",
          RelayCommand.builder()
            .predicate(() => f.canCreateNew())
            .task(() => f.createNew())
            .build(),
        ),
      );
    }
    // Save / Delete target NoteVM (the only example-defined VM implementing
    // ISavable<T> / IDeletable<T>). Scenario §6.2: each note saves /
    // deletes itself. Reuse `note.saveCommand` / `note.deleteCommand`
    // directly so the action-bar Delete fires the same
    // ConfirmationDecoratorCommand (and "Note deleted" notification) that
    // the in-list delete button uses — keeping the action-bar and the
    // in-list delete button behaviorally identical (parity with C#
    // CapabilityActionsVM.cs:121-131).
    if (focused instanceof NoteVM) {
      const note = focused;
      if (hasCapability(focused, "ISavable")) {
        out.push(makeActionVM("Save", note.saveCommand));
      }
      if (hasCapability(focused, "IDeletable")) {
        out.push(makeActionVM("Delete", note.deleteCommand));
      }
    }
    if (hasCapability(focused, "IReconstructable")) {
      const f = focused as ReconstructShape;
      out.push(
        makeActionVM(
          "Reconstruct",
          RelayCommand.builder()
            .predicate(() => f.canReconstruct())
            .task(() => f.reconstruct())
            .build(),
        ),
      );
    }
    return out;
  }

  protected override _onDispose(): void {
    this.#actionsDerived.dispose();
    this.#addNoteCommand.dispose();
    this.#focusSubject.complete();
    super._onDispose();
  }

  static builder(): CapabilityActionsVMBuilder {
    return new CapabilityActionsVMBuilder();
  }
}

export class CapabilityActionsVMBuilder {
  #name: string | null = null;
  #hint = "";
  #hub: IMessageHub | null = null;
  #dispatcher: IDispatcher | null = null;
  #focusedGetter: FocusedGetter | null = null;
  #addNoteAction: (() => void | Promise<void>) | null = null;
  #canAddNote: (() => boolean) | null = null;

  constructor(from?: CapabilityActionsVMBuilder) {
    if (from) {
      this.#name = from.#name;
      this.#hint = from.#hint;
      this.#hub = from.#hub;
      this.#dispatcher = from.#dispatcher;
      this.#focusedGetter = from.#focusedGetter;
      this.#addNoteAction = from.#addNoteAction;
      this.#canAddNote = from.#canAddNote;
    }
  }

  name(value: string): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#name = value;
    return b;
  }

  hint(value: string): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#hint = value;
    return b;
  }

  services(
    hub: IMessageHub,
    dispatcher: IDispatcher,
  ): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#hub = hub;
    b.#dispatcher = dispatcher;
    return b;
  }

  focusedGetter(getter: FocusedGetter): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#focusedGetter = getter;
    return b;
  }

  /** Wire the *Add Note* command body (edge-case backfill). */
  addNoteAction(action: () => void | Promise<void>): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#addNoteAction = action;
    return b;
  }

  /**
   * Wire the *Add Note* command can-execute predicate.
   *
   * Used by `WorkspaceVM` to consult `notesView.currentNotebookIsReadonly`
   * so the bar disables *Add Note* against readonly notebooks.
   */
  canAddNote(predicate: () => boolean): CapabilityActionsVMBuilder {
    const b = new CapabilityActionsVMBuilder(this);
    b.#canAddNote = predicate;
    return b;
  }

  build(): CapabilityActionsVM {
    if (this.#name === null) throw new Error("name is required");
    if (this.#hub === null || this.#dispatcher === null)
      throw new Error("services are required");
    if (this.#focusedGetter === null)
      throw new Error("focusedGetter is required");
    return new CapabilityActionsVM({
      name: this.#name,
      hint: this.#hint,
      hub: this.#hub,
      dispatcher: this.#dispatcher,
      focusedGetter: this.#focusedGetter,
      ...(this.#addNoteAction !== null
        ? { addNoteAction: this.#addNoteAction }
        : {}),
      ...(this.#canAddNote !== null ? { canAddNote: this.#canAddNote } : {}),
    });
  }
}

import { execSync } from "node:child_process";
import { existsSync, readdirSync } from "node:fs";
import { dirname, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import type { TestProject } from "vitest/node";

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const generatedDirectories = ["dist", "src/fixtures", "src/conformance/schemas"].map(
  (directory) => resolve(packageRoot, directory),
);

export function isGeneratedBuildPath(file: string): boolean {
  const absolute = resolve(file);
  return generatedDirectories.some(
    (directory) => absolute === directory || absolute.startsWith(`${directory}${sep}`),
  );
}

function generatedFiles(): string[] {
  return generatedDirectories.flatMap((directory) =>
    existsSync(directory)
      ? readdirSync(directory).map((file) => resolve(directory, file))
      : [],
  );
}

function build(project: TestProject): void {
  const previous = generatedFiles();
  execSync("npm run build", { cwd: packageRoot, stdio: "inherit" });
  // The watcher ignores generated writes; invalidate old and new chunk names.
  for (const file of new Set([...previous, ...generatedFiles()])) {
    project.vitest.invalidateFile(file);
  }
}

export default function setup(project: TestProject): void {
  build(project);
  project.onTestsRerun(async () => {
    // Manual reruns may be requested while the preceding workers are active.
    await project.vitest.waitForTestRunEnd();
    build(project);
  });
}

/**
 * Vitest global setup — rxjs unhandled-error policy.
 *
 * rxjs v7 routes synchronous exceptions thrown inside subscriber next-handlers
 * through reportUnhandledError, which surfaces them via setTimeout(0) AFTER any
 * try-catch boundary. The HUB-007 tests intentionally trigger a throwing
 * subscriber, so these reports are expected there.
 *
 * VMX-085: previously this file installed a PERMANENT global no-op on
 * `config.onUnhandledError`, which swallowed every rxjs unhandled error
 * suite-wide — masking a genuine unhandled error in any unrelated test. Instead
 * we now RECORD unhandled errors and, by default, surface them as a test
 * failure in `afterEach`. Tests that legitimately expect them (HUB-007) opt in
 * via {@link allowRxUnhandledErrors}, scoping the suppression to exactly those
 * tests.
 */
import { config } from "rxjs";
import { afterEach } from "vitest";

let _expecting = false;
const _recorded: unknown[] = [];

config.onUnhandledError = (err: unknown) => {
  _recorded.push(err);
};

/**
 * Opt the current test in to tolerating rxjs "unhandled error" reports (e.g.
 * HUB-007's intentionally-throwing subscriber, whose error rxjs routes through
 * reportUnhandledError on a macrotask). Auto-resets after each test.
 */
export function allowRxUnhandledErrors(): void {
  _expecting = true;
}

afterEach(async () => {
  // rxjs surfaces unhandled errors on a macrotask (setTimeout(0)); drain the
  // queue so a throw from the just-finished test is captured here before we
  // decide whether it was expected.
  await new Promise((resolve) => setTimeout(resolve, 0));
  const recorded = _recorded.splice(0);
  const expecting = _expecting;
  _expecting = false;
  if (!expecting && recorded.length > 0) {
    const errors = recorded.map((e) =>
      e instanceof Error ? e : new Error(String(e)),
    );
    throw new AggregateError(
      errors,
      `Unexpected rxjs unhandled error(s) surfaced during this test: ${String(
        recorded.length,
      )}. If intentional (e.g. a HUB-007 throwing subscriber), call allowRxUnhandledErrors().`,
    );
  }
});
